const body = $json.body || $json;

const candidateId = body.candidateId || 'cand_demo_01';
const candidateName = body.name || body.candidateName || 'Ứng viên tiềm năng';
const candidateEmail = body.email || body.candidateEmail || 'candidate@example.com';
const jobTitle = body.jobTitle || 'Senior Software Engineer';
const matchScore = Number(body.matchScore || 85);
const skills = Array.isArray(body.parsedSkillsJson) ? body.parsedSkillsJson.join(', ') : (body.parsedSkillsJson || 'React, TypeScript, Node.js');

// Đề xuất ngày phỏng vấn sau 3 ngày làm việc vào lúc 09:30 AM (GMT+7)
const interviewDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000);
interviewDate.setHours(9, 30, 0, 0);
const formattedDate = interviewDate.toLocaleDateString('vi-VN', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});
const formattedTime = '09:30 - 10:30 (Giờ Việt Nam)';

// Tạo link Google Meet tự động
const randomRoomId = Math.random().toString(36).substring(2, 6) + '-' + Math.random().toString(36).substring(2, 6) + '-' + Math.random().toString(36).substring(2, 5);
const googleMeetUrl = `https://meet.google.com/${randomRoomId}`;

// Soạn email HTML chuyên nghiệp
const emailHtml = `
<div style="font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; max-width: 600px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);">
  <div style="background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%); padding: 32px 24px; text-align: center; color: #ffffff;">
    <h1 style="margin: 0; font-size: 24px; font-weight: 800; letter-spacing: -0.5px;">THƯ MỜI PHỎNG VẤN TRỰC TUYẾN</h1>
    <p style="margin: 8px 0 0 0; font-size: 14px; opacity: 0.9;">AI Recruitment Agent • HR Tech Platform</p>
  </div>
  <div style="padding: 32px 24px; color: #1e293b;">
    <p style="font-size: 15px; line-height: 1.6; margin-top: 0;">Kính gửi <strong>${candidateName}</strong>,</p>
    <p style="font-size: 14px; line-height: 1.6; color: #334155;">
      Chúc mừng bạn! Hồ sơ ứng tuyển của bạn cho vị trí <strong>${jobTitle}</strong> đã được hệ thống <strong>AI Recruitment Agent</strong> đánh giá rất cao với điểm tương thích ấn tượng <strong><span style="color: #16a34a; font-size: 16px;">${matchScore}%</span></strong>.
    </p>
    <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 12px; padding: 20px; margin: 24px 0;">
      <h3 style="margin: 0 0 12px 0; font-size: 14px; text-transform: uppercase; color: #4f46e5; font-weight: 700;">Chi tiết buổi phỏng vấn</h3>
      <table style="width: 100%; font-size: 13px; line-height: 1.8; color: #475569;">
        <tr><td style="width: 130px; font-weight: 600;">Vị trí:</td><td>${jobTitle}</td></tr>
        <tr><td style="font-weight: 600;">Thời gian:</td><td><strong>${formattedTime}</strong>, ${formattedDate}</td></tr>
        <tr><td style="font-weight: 600;">Hình thức:</td><td>Trực tuyến qua Google Meet</td></tr>
        <tr><td style="font-weight: 600;">Đường dẫn phòng:</td><td><a href="${googleMeetUrl}" style="color: #4f46e5; font-weight: 700; text-decoration: none;">${googleMeetUrl}</a></td></tr>
      </table>
    </div>
    <div style="text-align: center; margin: 30px 0;">
      <a href="${googleMeetUrl}" style="background: #4f46e5; color: #ffffff; padding: 12px 28px; border-radius: 8px; font-weight: 700; text-decoration: none; display: inline-block; font-size: 14px; box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3);">Tham gia phòng họp Google Meet</a>
    </div>
    <p style="font-size: 13px; color: #64748b; line-height: 1.6;">
      Vui lòng kiểm tra camera và micro trước giờ phỏng vấn 5 phút. Nếu cần thay đổi thời gian, bạn có thể phản hồi trực tiếp qua email này.
    </p>
    <p style="font-size: 13px; color: #64748b; margin-bottom: 0;">Trân trọng,<br><strong>Ban Tuyển dụng & AI Recruitment Squad</strong></p>
  </div>
</div>
`;

return [{
  json: {
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    matchScore,
    skills,
    formattedDate,
    formattedTime,
    googleMeetUrl,
    emailSubject: `[HR Platform] Thư mời phỏng vấn vị trí ${jobTitle} - ${candidateName}`,
    emailHtml
  }
}];

const scheduleData = $('Tạo Lịch Phỏng Vấn & Phòng Google Meet').first().json;

return [{
  json: {
    success: true,
    action: 'INTERVIEW_SCHEDULED',
    candidateId: scheduleData.candidateId,
    candidateName: scheduleData.candidateName,
    candidateEmail: scheduleData.candidateEmail,
    jobTitle: scheduleData.jobTitle,
    matchScore: scheduleData.matchScore,
    interviewTime: scheduleData.formattedTime,
    interviewDate: scheduleData.formattedDate,
    googleMeetUrl: scheduleData.googleMeetUrl,
    scheduledAt: new Date().toISOString()
  }
}];
